document.addEventListener('DOMContentLoaded', function() {
  const articlesContainer = document.createElement('div');
  articlesContainer.id = 'articles-table-container';
  document.body.appendChild(articlesContainer);

  const articlesTitle = document.createElement('h2');
  articlesTitle.textContent = 'Articles Table';
  articlesContainer.appendChild(articlesTitle);

  const articlesDownloadBtn = document.createElement('button');
  articlesDownloadBtn.textContent = 'Download Table Data';
  articlesDownloadBtn.onclick = function() {
    articlesTable.download('csv', 'articles_table.csv');
  };
  articlesContainer.appendChild(articlesDownloadBtn);

  const articlesTableDiv = document.createElement('div');
  articlesTableDiv.id = 'articles-table';
  articlesContainer.appendChild(articlesTableDiv);

  const articlesTable = new Tabulator('#articles-table', {
    data: articlesTableData,
    layout: 'fitColumns',
    pagination: 'local',
    paginationSize: 20,
    initialSort:[
      {column:'citations', dir:'desc'}
    ],
    columns: [
      {
        title: 'Title', field: 'title', sorter: 'string', headerFilter: 'input',
        formatter: function(cell) {
          const value = cell.getValue();
          const url = cell.getRow().getData().url;
          return url && url !== 'N/A' ? `<a href='${url}' target='_blank'>${value}</a>` : value;
        }
      },
      { title: 'Journal/Publisher', field: 'journal', sorter: 'string', headerFilter: 'input' },
      { title: 'Type', field: 'type', sorter: 'string', headerFilter: 'input' },
      { title: 'Year', field: 'year', sorter: 'number', headerFilter: 'input' },
      { title: 'Citations', field: 'citations', sorter: 'number', headerFilter: 'input' }
    ]
  });
});
